import{_ as n,C as i,c as l,o as t,j as s,b as u,a2 as c,a,w as o,G as p,a3 as d}from"./chunks/framework.DkPtUiZm.js";const L=JSON.parse('{"title":"Tous les composants dans la démonstration web","description":"","frontmatter":{},"headers":[],"relativePath":"guides/catalogue-web.md","filePath":"guides/catalogue-web.md","lastUpdated":1795096530000}'),m={name:"guides/catalogue-web.md"};function g(h,e,f,b,x,v){const r=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=s("h1",{id:"tous-les-composants-dans-la-demonstration-web",tabindex:"-1"},[a("Tous les composants dans la démonstration web "),s("a",{class:"header-anchor",href:"#tous-les-composants-dans-la-demonstration-web","aria-label":'Permalink to "Tous les composants dans la démonstration web"'},"​")],-1)),e[2]||(e[2]=s("p",null,[a("La démonstration web s’ouvre maintenant sur "),s("strong",null,"Composants → Tous"),a(". Le catalogue référence les 115 modules de composants du registre public, avec noms, descriptions, familles, statut du registre, aperçus et variantes.")],-1)),(t(),u(d,null,{default:o(()=>[p(r,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20LR%0A%20%20Registry%5B%22Registre%20et%20sources%20des%20composants%22%5D%20--%3E%20Build%5B%22Catalogue%20g%C3%A9n%C3%A9r%C3%A9%20par%20Vite%22%5D%0A%20%20Docs%5B%22Descriptions%20Markdown%20et%20exemples%20existants%22%5D%20--%3E%20Build%0A%20%20Build%20--%3E%20Search%5B%22Recherche%2C%20famille%20et%20pagination%22%5D%0A%20%20Search%20--%3E%20Small%5B%22Aper%C3%A7us%20compacts%20imm%C3%A9diats%22%5D%0A%20%20Search%20--%3E%20Lazy%5B%22Exemples%20charg%C3%A9s%20%C3%A0%20la%20demande%22%5D%0A%20%20Lazy%20--%3E%20Variants%5B%22Variante%20choisie%20avec%20son%20%C3%A9tat%20local%22%5D%0A%20%20Search%20--%3E%20Flows%5B%22Parcours%20complets%20d%C3%A9j%C3%A0%20pr%C3%A9sents%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=c('<h2 id="parcourir-la-page" tabindex="-1">Parcourir la page <a class="header-anchor" href="#parcourir-la-page" aria-label="Permalink to &quot;Parcourir la page&quot;">​</a></h2><ul><li><strong>Tous</strong> est la première entrée du groupe Composants ; Vue d’ensemble et les scénarios métier restent accessibles.</li><li>Boutons, badges, spinners et contrôles courants apparaissent en premier.</li><li>La recherche porte sur noms, sous-composants, descriptions et alias français. Elle ignore casse et accents et accepte les pluriels courants.</li><li>Les familles filtrent la liste ; changer la recherche ou la famille revient à la première page. Douze fiches sont affichées par page.</li><li>Les contrôles compacts sont visibles immédiatement. Les grandes compositions se chargent avec <strong>Afficher l’aperçu</strong> ; elles ne démarrent pas toutes à la fois.</li><li><strong>Voir les variantes</strong> ouvre les exemples du composant dans la démonstration, sans nécessiter un second serveur Storybook. Le retour conserve les filtres.</li><li>Les compositions liées à une application, à un adaptateur de formulaire ou à la session renvoient vers leur parcours existant.</li></ul><p>Les statuts <strong>Stable</strong>, <strong>Expérimental</strong> et <strong>Déprécié</strong> viennent du registre. Ils n’indiquent pas une comparaison avec React Native. Le compteur porte sur les modules de composants ; une fiche peut exposer plusieurs sous-composants.</p><h2 id="theme-et-petits-ecrans" tabindex="-1">Thème et petits écrans <a class="header-anchor" href="#theme-et-petits-ecrans" aria-label="Permalink to &quot;Thème et petits écrans&quot;">​</a></h2><p>Le bouton clair/sombre reste accessible dans l’en-tête, y compris sur téléphone. Le panneau Personnalisation conserve les choix Clair, Sombre et Auto, ainsi que les couleurs et rayons. Les aperçus réutilisent le SiaProvider et les notifications de la démonstration. La pagination et les conteneurs défilants limitent les grands exemples sans faire déborder la page.</p><h2 id="source-unique-des-exemples" tabindex="-1">Source unique des exemples <a class="header-anchor" href="#source-unique-des-exemples" aria-label="Permalink to &quot;Source unique des exemples&quot;">​</a></h2><p><code>apps/docs/catalogue.ts</code> génère les métadonnées depuis le registre, les sources, les descriptions des composants et les fichiers d’exemples existants. Le module virtuel <code>virtual:sia-web-catalogue</code> fournit seulement ces métadonnées au navigateur : il n’embarque pas les fichiers Markdown et TypeScript bruts.</p><p><code>WebCatalogue.tsx</code> compose le catalogue et ses filtres. <code>WebExamples.tsx</code> réutilise le composant ou le rendu, les args et les décorateurs locaux des exemples. Les fonctions de test interactif et la barre de contrôle Storybook ne sont pas exécutées. Le choix d’une variante remonte uniquement son exemple ; un rendu ordinaire du catalogue ne recrée pas la fonction de composant contenant une saisie.</p><p>Les scénarios Sidebar/AppShell restent dans les pages déjà prévues pour eux. Les composants sans story autonome (Container et ColorModeToggle) possèdent un aperçu compact ; FormField et RequireSession utilisent leurs parcours existants.</p><p>Lors d’un ajout, le registre et l’exemple doivent rester cohérents. Les tests vérifient que l’inventaire correspond aux exports publics et que chaque fiche a un aperçu, un exemple ou un parcours. Le catalogue n’est pas une promesse que les scénarios d’une application réelle ont été validés.</p>',10))])}const C=n(m,[["render",g]]);export{L as __pageData,C as default};
